from solution import max_sub_array_sum_repeated


def test_issue_example_given():
    """Example from issue: repeating [10,20,-30,-1] 3 times gives 30."""
    assert max_sub_array_sum_repeated([10, 20, -30, -1], 4, 3) == 30  # 10+20=30


def test_issue_single_repetition_is_standard_max():
    """With k=1 the result is the largest sum of contiguous array in one copy."""
    assert max_sub_array_sum_repeated([-2, 1, -3, 4, -1, 2, 1, -5, 4], 9, 1) == 6  # 4-1+2+1=6


def test_issue_all_positive_scales_with_k():
    """Repeating an all-positive array concatenates, so the whole repeated array is best."""
    assert max_sub_array_sum_repeated([1, 2, 3], 3, 3) == 18  # (1+2+3)*3=6*3=18


def test_issue_all_negative_picks_largest_element():
    """Largest sum of contiguous array with all negatives is the least negative element."""
    assert max_sub_array_sum_repeated([-3, -1, -2], 3, 2) == -1  # max(-3,-1,-2)=-1


def test_issue_single_positive_element_repeated():
    """A single positive element repeated k times sums k copies together."""
    assert max_sub_array_sum_repeated([5], 1, 4) == 20  # 5+5+5+5=20


def test_issue_single_negative_element_repeated():
    """A single negative element repeated k times keeps the single element as best."""
    assert max_sub_array_sum_repeated([-5], 1, 3) == -5  # max(-5)=-5


def test_issue_best_crosses_one_boundary():
    """Modified array formed by repeating allows a subarray using suffix plus prefix."""
    assert max_sub_array_sum_repeated([8, -19, 8], 3, 2) == 16  # 8+8=16


def test_issue_zero_total_crosses_once():
    """With zero total sum, repeating once can join suffix and prefix across the boundary."""
    assert max_sub_array_sum_repeated([5, -10, 5], 3, 2) == 10  # 5+5=10


def test_contract_negative_total_does_not_grow_with_k():
    """Contract: repeating an array with negative total must not exceed one-copy best."""
    assert max_sub_array_sum_repeated([10, 20, -30, -1], 4, 2) == 30  # 10+20=30


def test_contract_positive_total_uses_whole_repeated_array():
    """Contract: repeating an array with positive total can take the whole repeated array."""
    assert max_sub_array_sum_repeated([5, -3, 5], 3, 2) == 14  # 5-3+5+5-3+5=14


def test_contract_large_k_with_positive_total():
    """Contract: repeated concatenation for large k adds each middle copy fully when total is positive."""
    assert max_sub_array_sum_repeated([1, 2, -1], 3, 5) == 11  # 2*5+1=10+1=11
